select throws_ok(format('update public.profile_residences set time_zone = %L where user_id = %L', 'europe/london', :'person'), '23514', null, 'profile_residences.time_zone refuses "europe/london" (lower case)');
select is(app.is_valid_time_zone('Europe/london'), false, 'time zone "Europe/london" (mixed case)');
select throws_ok(format('update public.profile_residences set time_zone = %L where user_id = %L', 'Europe/london', :'person'), '23514', null, 'profile_residences.time_zone refuses "Europe/london" (mixed case)');
select is(app.is_valid_time_zone(' Europe/London'), false, 'time zone " Europe/London" (leading space)');
select throws_ok(format('update public.profile_residences set time_zone = %L where user_id = %L', ' Europe/London', :'person'), '23514', null, 'profile_residences.time_zone refuses " Europe/London" (leading space)');
select is(app.is_valid_time_zone('Europe/London
'), false, 'time zone "Europe/London\n" (trailing line feed)');
select throws_ok(format('update public.profile_residences set time_zone = %L where user_id = %L', 'Europe/London
', :'person'), '23514', null, 'profile_residences.time_zone refuses "Europe/London\n" (trailing line feed)');
select is(app.is_valid_time_zone(''), false, 'time zone "" (empty)');
select throws_ok(format('update public.profile_residences set time_zone = %L where user_id = %L', '', :'person'), '23514', null, 'profile_residences.time_zone refuses "" (empty)');

